    /// The four Graphite values in `theme`, or nil when Graphite leaves the token unchanged.
    public func graphiteValues(theme: QuireTheme) -> QuireColorValues? {
        switch self {
        case .knob: return QuireThemeTable.knobGraphite[theme.index]
