    /// The token's Graphite stack (composited left to right), or nil when Graphite leaves it unchanged.
    public var graphiteStack: [String]? {
        switch self {
        case .knob: return ["paper"]
        case .accent: return ["ink"]
        case .accentFill: return ["ink"]
        case .accentFillHover: return ["ink2"]
        case .accentFillPressed: return ["ink3"]
        case .controlOnPressed: return ["ink3"]
        case .onAccent: return ["paper"]
        case .swipeArchive: return ["slip"]
        case .accentWash: return ["selWashIdle"]
        case .accentWashHover: return ["selWashIdle", "hover"]
        case .accentWashPressed: return ["selWashIdle", "pressed"]
        case .focus: return ["ink"]
        case .selWash: return ["selWashIdle"]
        case .selRule: return ["ink"]
        default: return nil
        }
    }

